<?php
declare(strict_types=1);require __DIR__.'/app.php';$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  try{verify_csrf();$email=strtolower(trim((string)($_POST['email']??'')));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Escribe un correo electrónico válido.');$s=db()->prepare('SELECT id,name,email FROM users WHERE email=? AND active=1 LIMIT 1');$s->execute([$email]);$user=$s->fetch();
    if($user){$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);db()->prepare('UPDATE password_reset_tokens SET used_at=NOW() WHERE user_id=? AND used_at IS NULL')->execute([$user['id']]);db()->prepare('INSERT INTO password_reset_tokens(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE))')->execute([$user['id'],$hash]);$url=rtrim($config['base_url'],'/').'/reset-password.php?token='.urlencode($token);$subject='Restablecer contraseña · Gimnasio Mutatio';$body="Hola {$user['name']},\n\nSolicitaste restablecer la contraseña de tu cuenta de Mutatio. Abre este enlace dentro de los próximos 30 minutos:\n\n{$url}\n\nSi no solicitaste este cambio, ignora el mensaje.\n";$headers='From: '.$config['mail_from']."\r\nContent-Type: text/plain; charset=UTF-8";@mail($user['email'],$subject,$body,$headers);}
    $message='Si el correo pertenece a una cuenta activa y el envío de correo está configurado, recibirás un enlace para restablecer la contraseña. El enlace vence en 30 minutos.';
  }catch(Throwable $e){$error=$e instanceof PDOException?'No fue posible procesar la solicitud. Verifica la base de datos y el correo.':$e->getMessage();}
}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recuperar contraseña · Mutatio</title><link rel="stylesheet" href="assets/app.css"><link rel="stylesheet" href="assets/extra.css"></head><body class="login-page"><main class="auth-wrap"><a class="login-brand" href="index.php"><span class="brand-mark">M</span><span>MUTATIO <small>TRAINING CLUB</small></span></a><section class="auth-card"><span class="eyebrow">RECUPERACIÓN DE ACCESO</span><h1>¿Olvidaste tu contraseña?</h1><p>Ingresa el correo asociado a tu cuenta y te enviaremos un enlace seguro.</p><?php if($error): ?><div class="alert error"><?=h($error)?></div><?php elseif($message): ?><div class="alert"><?=h($message)?></div><?php endif; ?><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>Correo electrónico<input type="email" name="email" required autocomplete="email" placeholder="tu@correo.com"></label><button class="btn primary wide">Enviar enlace de recuperación <span>↗</span></button></form><p class="auth-foot"><a href="index.php?view=login">← Volver al inicio de sesión</a></p><div class="auth-note">En XAMPP configura PHP mail/SMTP para recibir el enlace en tu correo.</div></section></main></body></html>
